CREATE TABLE subscription_plans (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), code TEXT NOT NULL UNIQUE, name TEXT NOT NULL, price BIGINT NOT NULL CHECK(price>=0), billing_cycle TEXT NOT NULL CHECK(billing_cycle IN ('MONTHLY','YEARLY')), max_listings INTEGER, features JSONB NOT NULL DEFAULT '[]', status TEXT NOT NULL DEFAULT 'ACTIVE', effective_from TIMESTAMPTZ NOT NULL DEFAULT now(), effective_to TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE subscriptions (id UUID PRIMARY KEY DEFAULT gen_random_uuid(), seller_id UUID NOT NULL REFERENCES users(id), plan_id UUID NOT NULL REFERENCES subscription_plans(id), price_snapshot BIGINT NOT NULL, status TEXT NOT NULL DEFAULT 'ACTIVE' CHECK(status IN ('ACTIVE','EXPIRED','CANCELLED')), starts_at TIMESTAMPTZ NOT NULL, ends_at TIMESTAMPTZ, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX subscriptions_seller_active_idx ON subscriptions(seller_id,status,ends_at);
